package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

/**
 * SPLIT PAYMENTS (standing orders to several payees)
 */
public class PaymentSplitter {

    /** Split payment into equal whole cents, leftover cents to the front. */
    public List<BigDecimal> split(BigDecimal total, int payees) {
        if (payees <= 0) {
            throw new IllegalArgumentException("PAYEES MUST BE POSITIVE");
        }

        BigInteger totalCents = total.movePointRight(2).toBigInteger();
        BigInteger numPayees = BigInteger.valueOf(payees);

        BigInteger[] sharesCents = new BigInteger[payees];
        BigInteger baseShare = totalCents.divide(numPayees);
        BigInteger remainder = totalCents.remainder(numPayees);

        for (int i = 0; i < payees; i++) {
            sharesCents[i] = baseShare;
            if (BigInteger.valueOf(i).compareTo(remainder) < 0) {
                sharesCents[i] = baseShare.add(BigInteger.ONE);
            }
        }

        List<BigDecimal> shares = new ArrayList<>(payees);
        for (BigInteger centAmount : sharesCents) {
            shares.add(new BigDecimal(centAmount).movePointLeft(2));
        }
        return shares;
    }
}
